"""
ACTIEPUNT 3: Portfolio Watch's '⚠️ Worth a closer look' toont nu
ALLEEN een dalende ROIC als die deze week VOOR HET EERST 'dalend' is
geworden -- niet meer elke week opnieuw dezelfde, allang-bekende daling
(bv. TSLA's YoY-dalende-ROIC, die anders elke week terug zou blijven
komen).

Nieuw:
- database.py: get_roic_trend_history() (haalt de vorige stand per
  ticker op) en save_roic_trend_history() (slaat de huidige stand op) --
  per TICKER bijgehouden (niet per gebruiker), want de ROIC-trend van een
  aandeel is voor iedereen hetzelfde.
- portfolio_watch.py: build_email_body() gebruikt nu 'roic_decline_is_new'
  i.p.v. simpelweg roic_trend=='dalend' -- met een terugval op het oude
  gedrag als die kolom ontbreekt (bv. bij handmatig testen). main()
  berekent deze kolom en slaat de nieuwe stand op na afloop.
- weekly_batch.py: dezelfde logica toegevoegd in de multi-user
  run_portfolio_emails()-functie.

Gebruik: python fix_roic_new_decline_only.py
Draai dit vanuit je stock_screener-map (hestys-fresh).

BELANGRIJK -- draai deze SQL in Supabase's SQL Editor voor de nieuwe tabel:
    create table roic_trend_history (
        ticker text primary key,
        last_roic_trend text,
        last_checked_at timestamp with time zone default now()
    );
"""

PORTFOLIO_WATCH_CONTENT = b'"""\r\nPortfolio Watch: volgt de HUIDIGE Supertrend-status van je eigen bestaande\r\nposities (in tegenstelling tot screener.py, dat naar NIEUWE idee\xc3\xabn in\r\nAEX/Nasdaq-100 zoekt). Dit is vooral relevant bij een geconcentreerde\r\nportfolio -- weten of je grootste positie (bv. Tesla) nog steeds in een\r\nbullish trend zit, is vaak belangrijker dan een willekeurig nieuw signaal.\r\n\r\nHaalt je posities nu RECHTSTREEKS uit de database (dezelfde die \'My\r\nPortfolio\' op de site gebruikt), i.p.v. een hardgecodeerde lijst die\r\nhandmatig bijgewerkt moest worden -- deze mail blijft nu altijd\r\ngesynchroniseerd met wat je daadwerkelijk bezit, ook als je iets koopt\r\nof verkoopt. Alleen posities met shares > 0 worden meegenomen (geen\r\nwatchlist-items, geen posities die je al verkocht hebt).\r\n\r\nVereist: pip install -r requirements.txt\r\nVereist env-var: PORTFOLIO_WATCH_USER_EMAIL (welk account de posities gevolgd worden)\r\n\r\nGebruik: python portfolio_watch.py\r\n"""\r\nfrom __future__ import annotations\r\n\r\nimport os\r\n\r\nimport pandas as pd\r\nimport yfinance as yf\r\n\r\nfrom indicators import supertrend, ema, resample_to_weekly\r\nfrom screener import get_roic_data, fetch_weekly, get_earnings_surprise\r\nfrom emailer import send_email, is_configured as email_is_configured\r\nfrom database import get_user_holdings, get_roic_trend_history, save_roic_trend_history\r\n\r\n\r\ndef get_current_holdings() -> list:\r\n    """\r\n    Haalt de ACTUELE, eigen posities op uit de database (i.p.v. een\r\n    hardgecodeerde lijst) -- alleen posities met shares > 0 (geen\r\n    watchlist-items, geen verkochte posities). Vereist de env-var\r\n    PORTFOLIO_WATCH_USER_EMAIL, zodat dit script weet WELK account\r\n    gevolgd moet worden (het draait immers los van een ingelogde sessie).\r\n    """\r\n    user_email = os.getenv("PORTFOLIO_WATCH_USER_EMAIL")\r\n    if not user_email:\r\n        raise ValueError(\r\n            "PORTFOLIO_WATCH_USER_EMAIL is niet ingesteld -- Portfolio Watch weet "\r\n            "hierdoor niet welk account de posities gevolgd moeten worden."\r\n        )\r\n    all_holdings = get_user_holdings(user_email, is_watchlist=False)\r\n    return [\r\n        {"naam": h["naam"], "ticker": h["ticker"], "shares": h["shares"]}\r\n        for h in all_holdings\r\n        if (h.get("shares") or 0) > 0\r\n    ]\r\n\r\nATR_LENGTH = 6\r\nATR_MULTIPLIER = 2.6\r\nTREND_FILTER_EMA_LENGTH = 20\r\nRECENT_CHANGE_WEEKS = 2  # een statusverandering binnen dit aantal weken wordt als \'LET OP\' gemarkeerd\r\nEARNINGS_RECENT_DAYS = 7  # hoe recent gerapporteerde cijfers moeten zijn om als \'deze week\' te tellen\r\n\r\n\r\ndef get_upcoming_earnings_date(ticker: str):\n    """\n    Checkt of deze positie AANKOMENDE cijfers heeft binnen de komende 7\n    dagen -- vooruitkijkend, in tegenstelling tot get_earnings_surprise()\n    (die kijkt naar AL gerapporteerde cijfers). Geeft None terug als er\n    geen aankomende cijfers binnen dat venster zijn, of als het niet op\n    te halen is.\n    """\n    try:\n        earnings_dates = yf.Ticker(ticker).get_earnings_dates(limit=8)\n        if earnings_dates is None or earnings_dates.empty:\n            return None\n        today = pd.Timestamp.now(tz=earnings_dates.index.tz).normalize()\n        window_end = today + pd.Timedelta(days=7)\n        future_dates = earnings_dates.index[(earnings_dates.index >= today) & (earnings_dates.index <= window_end)]\n        return future_dates[0] if len(future_dates) > 0 else None\n    except Exception:\n        return None\n\n\ndef check_holding(naam: str, ticker: str):\r\n    # Earnings-verrassing (al gerapporteerd) EN aankomende earnings (komende\r\n    # 7 dagen) zijn allebei onafhankelijk van of er genoeg historie is voor\r\n    # Supertrend -- altijd proberen op te halen, ook als de technische check\r\n    # hieronder faalt.\r\n    earnings_info = get_earnings_surprise(ticker)\r\n    upcoming_earnings = get_upcoming_earnings_date(ticker)\r\n\r\n    try:\r\n        df = fetch_weekly(ticker)\r\n    except Exception as exc:\r\n        print(f"  {naam} ({ticker}): fout bij ophalen ({exc})")\r\n        return {\r\n            "naam": naam, "ticker": ticker, "status": "ONBEKEND (fout bij ophalen)",\r\n            "sinds": None, "weken_in_trend": None, "recent_gewijzigd": False,\r\n            "prijs": None, "boven_ema20": None, "roic_pct": None, "roic_trend": "onbekend",\r\n            "week_change_pct": None,\r\n            "earnings_surprise_pct": earnings_info["surprise_pct"],\r\n            "earnings_beat": earnings_info["beat"],\r\n            "earnings_date": earnings_info["earnings_date"],\r\n            "upcoming_earnings_date": upcoming_earnings,\r\n        }\r\n\r\n    min_needed = max(ATR_LENGTH, TREND_FILTER_EMA_LENGTH) + 5\r\n    if df.empty or len(df) < min_needed:\r\n        print(f"  {naam} ({ticker}): te weinig data voor Supertrend (nodig: {min_needed}, "\r\n              f"gekregen: {len(df)})")\r\n        latest_price = round(float(df[\'close\'].iloc[-1]), 2) if not df.empty else None\r\n        week_change_pct = None\r\n        if len(df) >= 2:\r\n            prev_close = float(df["close"].iloc[-2])\r\n            if prev_close:\r\n                week_change_pct = (float(df["close"].iloc[-1]) - prev_close) / prev_close * 100\r\n        return {\r\n            "naam": naam, "ticker": ticker, "status": "ONBEKEND (te weinig historie)",\r\n            "sinds": None, "weken_in_trend": None, "recent_gewijzigd": False,\r\n            "prijs": latest_price, "boven_ema20": None, "roic_pct": None, "roic_trend": "onbekend",\r\n            "week_change_pct": week_change_pct,\r\n            "earnings_surprise_pct": earnings_info["surprise_pct"],\r\n            "earnings_beat": earnings_info["beat"],\r\n            "earnings_date": earnings_info["earnings_date"],\r\n            "upcoming_earnings_date": upcoming_earnings,\r\n        }\r\n\r\n    st = supertrend(df, length=ATR_LENGTH, multiplier=ATR_MULTIPLIER)\r\n    df = df.copy()\r\n    df["trend_dir"] = st["trend_dir"]\r\n    df["ema_trend"] = ema(df["close"], TREND_FILTER_EMA_LENGTH)\r\n\r\n    current_trend = int(df["trend_dir"].iloc[-1])\r\n    trend_changes = df.index[df["trend_dir"] != df["trend_dir"].shift(1)]\r\n    last_change = trend_changes[-1] if len(trend_changes) > 0 else df.index[0]\r\n    weeks_in_current_trend = len(df.loc[last_change:]) - 1\r\n\r\n    latest_row = df.iloc[-1]\r\n    roic_data = get_roic_data(ticker)\r\n\r\n    prev_close = float(df["close"].iloc[-2])\r\n    week_change_pct = (float(latest_row["close"]) - prev_close) / prev_close * 100 if prev_close else None\r\n\r\n    return {\r\n        "naam": naam,\r\n        "ticker": ticker,\r\n        "status": "BULLISH" if current_trend == 1 else "BEARISH",\r\n        "sinds": last_change.date(),\r\n        "weken_in_trend": weeks_in_current_trend,\r\n        "recent_gewijzigd": weeks_in_current_trend <= RECENT_CHANGE_WEEKS,\r\n        "prijs": round(float(latest_row["close"]), 2),\r\n        "boven_ema20": bool(latest_row["close"] > latest_row["ema_trend"]),\r\n        "roic_pct": round(roic_data["roic"] * 100, 1) if roic_data["roic"] is not None else None,\r\n        "roic_trend": roic_data["roic_trend"],\r\n        "week_change_pct": week_change_pct,\r\n        "earnings_surprise_pct": earnings_info["surprise_pct"],\r\n        "earnings_beat": earnings_info["beat"],\r\n        "earnings_date": earnings_info["earnings_date"],\r\n        "upcoming_earnings_date": upcoming_earnings,\r\n    }\r\n\r\n\r\ndef build_email_body(df: pd.DataFrame) -> tuple:\r\n    """Bouwt de Portfolio Watch-mail -- zelfde Hesty\'s-stijl als de dagelijkse/wekelijkse signalen-mails."""\r\n    changed = df[df["recent_gewijzigd"]]\r\n\r\n    # --- Beknopt: alleen wat DEZE WEEK daadwerkelijk is veranderd, i.p.v.\r\n    # een volledige, elke-keer-herhalende samenvatting van alles. ---\r\n    from datetime import datetime as _datetime\r\n\r\n    def _is_recent_earnings(earnings_date):\r\n        if earnings_date is None:\r\n            return False\r\n        try:\r\n            ed = earnings_date.date() if hasattr(earnings_date, "date") else earnings_date\r\n            days_since = (_datetime.now().date() - ed).days\r\n            return 0 <= days_since <= EARNINGS_RECENT_DAYS\r\n        except Exception:\r\n            return False\r\n\r\n    earnings_mask = df["earnings_date"].apply(_is_recent_earnings) & df["earnings_surprise_pct"].notna()\r\n    earnings_this_week = df[earnings_mask]\r\n\r\n    upcoming_earnings = df[df["upcoming_earnings_date"].notna()].sort_values("upcoming_earnings_date")\r\n\r\n    # --- Fundamentele signalen: NIEUWE dalende ROIC (dus: deze week voor\r\n    # het eerst \'dalend\', niet al weken bekend -- anders zou dit elke week\r\n    # opnieuw dezelfde, allang-bekende trend melden) EN/OF een recente\r\n    # earnings-misser -- allebei zaken die je mening over een positie\r\n    # zouden kunnen bijstellen, in tegenstelling tot een neutrale\r\n    # trend-flip of een earnings-beat.\r\n    #\r\n    # \'roic_decline_is_new\' wordt door de aanroeper vooraf berekend (via\r\n    # database.get_roic_trend_history()) -- vergelijkt de HUIDIGE\r\n    # roic_trend met de LAATST BEKENDE stand van vorige week. Als deze\r\n    # kolom ontbreekt (bv. bij handmatig testen zonder database-koppeling),\r\n    # valt dit terug op het oude gedrag (elke \'dalend\' telt mee) i.p.v. te\r\n    # crashen. ---\r\n    has_new_roic_column = "roic_decline_is_new" in df.columns\r\n\r\n    def _fundamental_reason(row):\r\n        reasons = []\r\n        is_new_decline = row["roic_decline_is_new"] if has_new_roic_column else (row["roic_trend"] == "dalend")\r\n        if is_new_decline:\r\n            reasons.append("ROIC just turned declining year-over-year")\r\n        if earnings_mask.get(row.name, False) and row["earnings_beat"] is False:\r\n            reasons.append(f"missed earnings estimates by {row[\'earnings_surprise_pct\']:+.1f}%")\r\n        return " and ".join(reasons)\r\n\r\n    if has_new_roic_column:\r\n        roic_flag = df["roic_decline_is_new"]\r\n    else:\r\n        roic_flag = df["roic_trend"] == "dalend"\r\n    fundamental_mask = roic_flag | (earnings_mask & (df["earnings_beat"] == False))\r\n    fundamental_concerns = df[fundamental_mask].copy()\r\n    if not fundamental_concerns.empty:\r\n        fundamental_concerns["reason"] = fundamental_concerns.apply(_fundamental_reason, axis=1)\r\n\r\n    notable_tickers = set(changed["ticker"]) | set(earnings_this_week["ticker"]) | set(fundamental_concerns["ticker"])\r\n    quiet_positions = df[~df["ticker"].isin(notable_tickers)]\r\n\r\n    # --- Gewogen weekrendement + beste/slechtste positie deze week --\r\n    # gewogen op huidige positiewaarde (shares x prijs), zodat een grote\r\n    # positie logischerwijs zwaarder meetelt dan een kleine.\r\n    df_with_value = df.copy()\r\n    df_with_value["value"] = df_with_value["shares"].fillna(0) * df_with_value["prijs"].fillna(0)\r\n    valid_week = df_with_value[df_with_value["week_change_pct"].notna() & (df_with_value["value"] > 0)]\r\n    portfolio_week_change_pct = None\r\n    if not valid_week.empty and valid_week["value"].sum() > 0:\r\n        portfolio_week_change_pct = (valid_week["week_change_pct"] * valid_week["value"]).sum() / valid_week["value"].sum()\r\n\r\n    best_this_week = worst_this_week = None\r\n    valid_week_moves = df[df["week_change_pct"].notna()]\r\n    if not valid_week_moves.empty:\r\n        best_this_week = valid_week_moves.loc[valid_week_moves["week_change_pct"].idxmax()]\r\n        worst_this_week = valid_week_moves.loc[valid_week_moves["week_change_pct"].idxmin()]\r\n        if best_this_week["ticker"] == worst_this_week["ticker"]:\r\n            worst_this_week = None  # slechts 1 positie met bekende weekbeweging -- niet 2x dezelfde tonen\r\n\r\n    # --- Tekst-versie ---\r\n    text_lines = ["Good morning from Hesty\'s -- here\'s your portfolio watch.", ""]\r\n\r\n    if portfolio_week_change_pct is not None:\r\n        text_lines.append(f"\xf0\x9f\x93\x88 Your portfolio this week: {portfolio_week_change_pct:+.1f}%")\r\n        if best_this_week is not None:\r\n            text_lines.append(f"  Best: {best_this_week[\'naam\']} ({best_this_week[\'ticker\']}) {best_this_week[\'week_change_pct\']:+.1f}%")\r\n        if worst_this_week is not None:\r\n            text_lines.append(f"  Worst: {worst_this_week[\'naam\']} ({worst_this_week[\'ticker\']}) {worst_this_week[\'week_change_pct\']:+.1f}%")\r\n        text_lines.append("")\r\n\r\n    if len(changed) > 0:\r\n        text_lines.append("\xf0\x9f\x94\x84 Trend changes this week:")\r\n        for _, row in changed.iterrows():\r\n            emoji = "\xf0\x9f\x9f\xa2" if row["status"] == "BULLISH" else "\xf0\x9f\x94\xb4"\r\n            text_lines.append(f"  {emoji} {row[\'naam\']} ({row[\'ticker\']}): flipped to {row[\'status\']}")\r\n    else:\r\n        text_lines.append("\xf0\x9f\x94\x84 No trend changes this week.")\r\n    text_lines.append("")\r\n\r\n    if not fundamental_concerns.empty:\r\n        text_lines.append("\xe2\x9a\xa0\xef\xb8\x8f Worth a closer look:")\r\n        for _, row in fundamental_concerns.iterrows():\r\n            text_lines.append(f"  - {row[\'naam\']} ({row[\'ticker\']}): {row[\'reason\']}")\r\n        text_lines.append("")\r\n\r\n    if len(earnings_this_week) > 0:\r\n        text_lines.append("\xf0\x9f\x93\x8a Earnings this week:")\r\n        for _, row in earnings_this_week.iterrows():\r\n            beat_txt = "beat" if row["earnings_beat"] else "missed"\r\n            text_lines.append(f"  - {row[\'naam\']} ({row[\'ticker\']}): {beat_txt} estimates by {row[\'earnings_surprise_pct\']:+.1f}%")\r\n        text_lines.append("")\r\n\r\n    if len(upcoming_earnings) > 0:\r\n        text_lines.append("\xf0\x9f\x93\x85 Earnings coming up next week:")\r\n        for _, row in upcoming_earnings.iterrows():\r\n            earnings_date_str = row["upcoming_earnings_date"].strftime("%A %Y-%m-%d")\r\n            text_lines.append(f"  - {row[\'naam\']} ({row[\'ticker\']}): {earnings_date_str}")\r\n        text_lines.append("")\r\n\r\n    if len(quiet_positions) > 0:\r\n        quiet_names = ", ".join(quiet_positions["ticker"].tolist())\r\n        text_lines.append(f"\xe2\x9c\x85 No notable changes ({len(quiet_positions)} position(s)): {quiet_names}")\r\n        text_lines.append("")\r\n\r\n    text_lines += [\r\n        "See the full picture under Analyze > Portfolio Overview on the site.",\r\n        "",\r\n        "-- Hesty\'s, your personal investment assistant",\r\n        "",\r\n        "This is a screener, not investment advice.",\r\n    ]\r\n    text_body = "\\n".join(text_lines)\r\n\r\n    # --- HTML-versie: zelfde donkere-header-met-jade-accent-stijl als de\r\n    # andere Hesty\'s-mails, maar nu bewust beknopt: korte secties i.p.v.\r\n    # een volledige tabel + nieuws-dump. ---\r\n    week_summary_html = ""\r\n    if portfolio_week_change_pct is not None:\r\n        week_color = "#0F8F6E" if portfolio_week_change_pct >= 0 else "#C1524A"\r\n        best_worst_bits = []\r\n        if best_this_week is not None:\r\n            best_worst_bits.append(\r\n                f"Best: <strong>{best_this_week[\'naam\']} ({best_this_week[\'ticker\']})</strong> "\r\n                f"<span style=\'color:#0F8F6E;\'>{best_this_week[\'week_change_pct\']:+.1f}%</span>"\r\n            )\r\n        if worst_this_week is not None:\r\n            best_worst_bits.append(\r\n                f"Worst: <strong>{worst_this_week[\'naam\']} ({worst_this_week[\'ticker\']})</strong> "\r\n                f"<span style=\'color:#C1524A;\'>{worst_this_week[\'week_change_pct\']:+.1f}%</span>"\r\n            )\r\n        best_worst_html = f"<p style=\'margin:6px 0 0 0; font-size:13px; color:#5B6472;\'>{\' &middot; \'.join(best_worst_bits)}</p>" if best_worst_bits else ""\r\n        week_summary_html = f"""\r\n        <div style="background:#F7F9FA; border-radius:8px; padding:14px 16px; margin-bottom:20px;">\r\n            <span style="font-size:14px; color:#5B6472;">\xf0\x9f\x93\x88 Your portfolio this week</span><br/>\r\n            <span style="font-size:22px; font-weight:700; color:{week_color};">{portfolio_week_change_pct:+.1f}%</span>\r\n            {best_worst_html}\r\n        </div>\r\n        """\r\n\r\n    def _flip_row_html(r):\r\n        emoji = "\xf0\x9f\x9f\xa2" if r["status"] == "BULLISH" else "\xf0\x9f\x94\xb4"\r\n        status_color = "#0F8F6E" if r["status"] == "BULLISH" else "#C1524A"\r\n        return (\r\n            f"<li style=\'padding:6px 0;\'>{emoji} <strong style=\'color:#101825;\'>{r[\'naam\']} ({r[\'ticker\']})</strong>: "\r\n            f"flipped to <span style=\'color:{status_color}; font-weight:600;\'>{r[\'status\']}</span></li>"\r\n        )\r\n\r\n    if len(changed) > 0:\r\n        flips_html = f"<ul style=\'margin:8px 0; padding-left:20px;\'>{\'\'.join(_flip_row_html(r) for _, r in changed.iterrows())}</ul>"\r\n    else:\r\n        flips_html = "<p style=\'color:#5B6472; margin:8px 0;\'>No trend changes this week.</p>"\r\n\r\n    fundamental_html = ""\r\n    if not fundamental_concerns.empty:\r\n        fundamental_items = "".join(\r\n            f"<li style=\'padding:6px 0;\'><strong style=\'color:#101825;\'>{r[\'naam\']} ({r[\'ticker\']})</strong>: "\r\n            f"<span style=\'color:#C1524A;\'>{r[\'reason\']}</span></li>"\r\n            for _, r in fundamental_concerns.iterrows()\r\n        )\r\n        fundamental_html = (\r\n            f"<h4 style=\'color:#101825; font-size:15px; margin:20px 0 4px 0;\'>\xe2\x9a\xa0\xef\xb8\x8f Worth a closer look</h4>"\r\n            f"<ul style=\'margin:8px 0; padding-left:20px;\'>{fundamental_items}</ul>"\r\n        )\r\n\r\n    def _earnings_row_html(r):\r\n        beat_txt = "beat" if r["earnings_beat"] else "missed"\r\n        color = "#0F8F6E" if r["earnings_beat"] else "#C1524A"\r\n        return (\r\n            f"<li style=\'padding:6px 0;\'><strong style=\'color:#101825;\'>{r[\'naam\']} ({r[\'ticker\']})</strong>: "\r\n            f"{beat_txt} estimates by <span style=\'color:{color}; font-weight:600;\'>{r[\'earnings_surprise_pct\']:+.1f}%</span></li>"\r\n        )\r\n\r\n    earnings_section_html = ""\r\n    if len(earnings_this_week) > 0:\r\n        earnings_items = "".join(_earnings_row_html(r) for _, r in earnings_this_week.iterrows())\r\n        earnings_section_html = (\r\n            f"<h4 style=\'color:#101825; font-size:15px; margin:20px 0 4px 0;\'>\xf0\x9f\x93\x8a Earnings this week</h4>"\r\n            f"<ul style=\'margin:8px 0; padding-left:20px;\'>{earnings_items}</ul>"\r\n        )\r\n\r\n    upcoming_earnings_html = ""\r\n    if len(upcoming_earnings) > 0:\r\n        upcoming_items = "".join(\r\n            f"<li style=\'padding:6px 0;\'><strong style=\'color:#101825;\'>{r[\'naam\']} ({r[\'ticker\']})</strong>: "\r\n            f"{r[\'upcoming_earnings_date\'].strftime(\'%A %Y-%m-%d\')}</li>"\r\n            for _, r in upcoming_earnings.iterrows()\r\n        )\r\n        upcoming_earnings_html = (\r\n            f"<h4 style=\'color:#101825; font-size:15px; margin:20px 0 4px 0;\'>\xf0\x9f\x93\x85 Earnings coming up next week</h4>"\r\n            f"<ul style=\'margin:8px 0; padding-left:20px;\'>{upcoming_items}</ul>"\r\n        )\r\n\r\n    quiet_html = ""\r\n    if len(quiet_positions) > 0:\r\n        quiet_names = ", ".join(quiet_positions["ticker"].tolist())\r\n        quiet_html = (\r\n            f"<p style=\'margin-top:20px; font-size:13px; color:#5B6472;\'>"\r\n            f"\xe2\x9c\x85 No notable changes ({len(quiet_positions)}): {quiet_names}</p>"\r\n        )\r\n\r\n    html_body = f"""\r\n    <div style="font-family: -apple-system, \'Segoe UI\', Roboto, Arial, sans-serif; max-width: 600px; margin: 0 auto; background:#ffffff;">\r\n        <div style="background:#101825; padding: 28px 24px; border-radius: 12px 12px 0 0;">\r\n            <div style="color:#1FAE96; font-size:13px; font-weight:600; letter-spacing:1px; text-transform:uppercase;">Hesty\'s Portfolio Watch</div>\r\n            <div style="color:#EAEDF1; font-size:22px; font-weight:700; margin-top:4px;">Your positions, checked</div>\r\n        </div>\r\n        <div style="padding: 24px; border: 1px solid #E5E8EC; border-top: none; border-radius: 0 0 12px 12px;">\r\n            {week_summary_html}\r\n            <h4 style="color:#101825; font-size:15px; margin:0 0 4px 0;">\xf0\x9f\x94\x84 Trend changes this week</h4>\r\n            {flips_html}\r\n            {fundamental_html}\r\n            {earnings_section_html}\r\n            {upcoming_earnings_html}\r\n            {quiet_html}\r\n            <p style="margin-top:20px; font-size:14px; color:#5B6472; line-height:1.5;">\r\n                See the full picture under\r\n                <a href="https://hestys.streamlit.app/?view=analyze&subview=portfolio" style="color:#1FAE96; font-weight:600; text-decoration:none;">Analyze &gt; Portfolio Overview</a> on the site.\r\n            </p>\r\n            <p style="margin-top:24px; font-size:14px; color:#101825; font-weight:600;">&mdash; Hesty\'s, your personal investment assistant</p>\r\n            <p style="margin-top:16px; font-size:12px; color:#9AA1AC; font-style:italic;">This is a screener, not investment advice.</p>\r\n        </div>\r\n    </div>\r\n    """\r\n    return text_body, html_body\r\n\r\n\r\ndef main() -> None:\r\n    portfolio_holdings = get_current_holdings()\r\n    print(f"Portfolio Watch: {len(portfolio_holdings)} posities checken "\r\n          f"(weekly, ATR-periode {ATR_LENGTH}, multiplier {ATR_MULTIPLIER})...\\n")\r\n\r\n    results = []\r\n    for holding in portfolio_holdings:\r\n        result = check_holding(holding["naam"], holding["ticker"])\r\n        if result:\r\n            result["shares"] = holding.get("shares")\r\n            results.append(result)\r\n            marker = " <-- LET OP, recent gewijzigd" if result["recent_gewijzigd"] else ""\r\n            if result["sinds"] is not None:\r\n                print(f"  {result[\'naam\']}: {result[\'status\']} sinds {result[\'sinds\']} "\r\n                      f"({result[\'weken_in_trend\']} weken){marker}")\r\n            else:\r\n                print(f"  {result[\'naam\']}: {result[\'status\']}")\r\n\r\n    if not results:\r\n        print("\\nGeen enkele positie kon gecheckt worden -- controleer je tickers.")\r\n        return\r\n\r\n    df = pd.DataFrame(results)\r\n    df.to_csv("portfolio_watch.csv", index=False)\r\n\r\n    print(f"\\n=== OVERZICHT ===\\n")\r\n    print(df.to_string(index=False))\r\n\r\n    print("\\nOpgeslagen in \'portfolio_watch.csv\'.")\r\n\r\n    # --- Alleen NIEUWE ROIC-dalingen laten meetellen in \'Worth a closer\r\n    # look\' -- vergelijkt met vorige week\'s bekende stand, i.p.v. elke\r\n    # week opnieuw dezelfde, allang-bekende daling te melden. ---\r\n    previous_roic_trends = get_roic_trend_history(df["ticker"].tolist())\r\n    df["roic_decline_is_new"] = df.apply(\r\n        lambda r: r["roic_trend"] == "dalend" and previous_roic_trends.get(r["ticker"]) != "dalend",\r\n        axis=1,\r\n    )\r\n\r\n    if email_is_configured():\r\n        text_body, html_body = build_email_body(df)\r\n        n_changed = int(df["recent_gewijzigd"].sum())\r\n        n_earnings = int((df["earnings_surprise_pct"].notna()).sum())\r\n        subject_parts = []\r\n        if n_changed > 0:\r\n            subject_parts.append(f"{n_changed} trend change(s)")\r\n        if n_earnings > 0:\r\n            subject_parts.append(f"{n_earnings} earnings update(s)")\r\n        subject = f"Portfolio Watch: {\', \'.join(subject_parts)}" if subject_parts else "Portfolio Watch: no notable changes this week"\r\n        send_email(subject=subject, body_text=text_body, body_html=html_body)\r\n    else:\r\n        print("\\n(E-mail niet verstuurd: nog niet ingesteld in .env.)")\r\n\r\n    # De HUIDIGE ROIC-stand opslaan als \'vorige week\' voor de volgende\r\n    # run -- onafhankelijk van of de mail daadwerkelijk verstuurd werd,\r\n    # want deze week se check heeft sowieso plaatsgevonden.\r\n    save_roic_trend_history(dict(zip(df["ticker"], df["roic_trend"])))\r\n\r\n\r\nif __name__ == "__main__":\r\n    main()\r\n'

DATABASE_CONTENT = b'"""\r\nDatabase-laag: leest en schrijft gebruikers-portfolio\'s in Supabase.\r\n\r\nFiltert ALTIJD op user_email in de Python-code zelf (zie supabase_schema.sql\r\nvoor de uitleg waarom dit hier gebeurt i.p.v. via Supabase\'s eigen\r\nrij-beveiliging -- we gebruiken Google-login via Streamlit, niet Supabase\'s\r\neigen inlogsysteem, dus die twee kunnen we niet automatisch koppelen).\r\n\r\nPRIVACY: elke functie hasht het e-mailadres intern (via hash_email()) v\xc3\xb3\xc3\xb3rdat\r\nhet als sleutel in de database wordt gebruikt. Dat betekent: wie rechtstreeks\r\nin de Supabase-tabellen kijkt (bv. tijdens het debuggen van iets heel anders)\r\nziet een betekenisloze hash i.p.v. een naam/e-mailadres -- geen toevallige\r\nblik meer op wiens data dit is. De functies zelf blijven gewoon het ECHTE\r\ne-mailadres als input verwachten (zoals Streamlit\'s login dat geeft) -- de\r\naanroepers in dashboard.py hoeven dus niet te veranderen.\r\n\r\nVoor het daadwerkelijk VERSTUREN van mail (waar je het echte adres wel weer\r\nnodig hebt) bestaat een aparte, kleine \'user_identity\'-tabel die hash <-> echt\r\nadres onthoudt -- zie ensure_user_identity() en get_real_email().\r\n"""\r\nfrom __future__ import annotations\r\n\r\nfrom datetime import datetime, timedelta\r\n\r\nimport streamlit as st\r\nfrom supabase import create_client, Client\r\n\r\nfrom user_hashing import hash_email\r\n\r\n\r\n@st.cache_resource\r\ndef get_supabase_client() -> Client:\r\n    url = st.secrets["supabase"]["url"]\r\n    key = st.secrets["supabase"]["anon_key"]\r\n    return create_client(url, key)\r\n\r\n\r\ndef ensure_user_identity(email: str, name: str = None) -> None:\r\n    """\r\n    Legt de koppeling hash <-> echt e-mailadres vast (of werkt \'m bij) --\r\n    nodig om later daadwerkelijk mail te kunnen sturen, want de rest van\r\n    de database slaat voortaan alleen de hash op. Veilig om bij elk\r\n    paginabezoek van een ingelogde gebruiker aan te roepen (idempotent).\r\n    """\r\n    client = get_supabase_client()\r\n    client.table("user_identity").upsert({\r\n        "email_hash": hash_email(email),\r\n        "email": email,\r\n        "name": name,\r\n    }, on_conflict="email_hash").execute()\r\n\r\n\r\ndef get_real_email(email_hash: str) -> str:\r\n    """\r\n    Zoekt het echte e-mailadres op bij een hash -- alleen gebruikt om\r\n    daadwerkelijk mail te kunnen versturen (in de batch-scripts), niet\r\n    door de normale app-functies zelf.\r\n    """\r\n    client = get_supabase_client()\r\n    response = client.table("user_identity").select("email").eq("email_hash", email_hash).execute()\r\n    if response.data:\r\n        return response.data[0]["email"]\r\n    return None\r\n\r\n\r\ndef get_user_holdings(user_email: str, is_watchlist: bool = False) -> list[dict]:\r\n    """Geeft alle EIGEN posities (is_watchlist=False) of alle WATCHLIST-items (True) van deze gebruiker terug."""\r\n    client = get_supabase_client()\r\n    response = client.table("portfolio_holdings").select("*") \\\r\n        .eq("user_email", hash_email(user_email)).eq("is_watchlist", is_watchlist).execute()\r\n    return response.data\r\n\r\n\r\ndef add_holding(user_email: str, naam: str, ticker: str, shares: float = None, is_watchlist: bool = False, isin: str = None) -> int:\r\n    """Voegt een nieuwe positie toe (eigen positie, of alleen watchlist als is_watchlist=True). Geeft de nieuwe id terug."""\r\n    client = get_supabase_client()\r\n    response = client.table("portfolio_holdings").insert({\r\n        "user_email": hash_email(user_email),\r\n        "naam": naam,\r\n        "ticker": ticker,\r\n        "shares": shares,\r\n        "position_value": None,  # wordt pas gevuld na de eerste \'Update waarde\'-klik\r\n        "is_watchlist": is_watchlist,\r\n        "isin": isin,\r\n    }).execute()\r\n    return response.data[0]["id"]\r\n\r\n\r\ndef update_holding_shares(holding_id: int, user_email: str, shares: float) -> None:\r\n    """Wijzigt het aantal shares/eenheden van een bestaande positie (zonder verwijderen+opnieuw-toevoegen)."""\r\n    client = get_supabase_client()\r\n    client.table("portfolio_holdings").update({"shares": shares}) \\\r\n        .eq("id", holding_id).eq("user_email", hash_email(user_email)).execute()\r\n\r\n\r\ndef add_transaction(\r\n    user_email: str, holding_id: int, transaction_type: str,\r\n    shares: float, price: float, fee: float, transaction_date: str,\r\n) -> None:\r\n    """\r\n    Logt 1 buy/sell-transactie voor een positie. Filtert ALTIJD op\r\n    user_email (zie de module-docstring voor waarom dit hier gebeurt).\r\n    """\r\n    client = get_supabase_client()\r\n    client.table("portfolio_transactions").insert({\r\n        "user_email": hash_email(user_email),\r\n        "holding_id": holding_id,\r\n        "transaction_type": transaction_type,\r\n        "shares": shares,\r\n        "price": price,\r\n        "fee": fee,\r\n        "transaction_date": transaction_date,\r\n    }).execute()\r\n\r\n\r\ndef get_transactions_for_holding(user_email: str, holding_id: int) -> list:\r\n    """Geeft alle transacties voor 1 positie terug, oudste eerst."""\r\n    client = get_supabase_client()\r\n    response = (\r\n        client.table("portfolio_transactions")\r\n        .select("*")\r\n        .eq("user_email", hash_email(user_email))\r\n        .eq("holding_id", holding_id)\r\n        .order("transaction_date", desc=False)\r\n        .execute()\r\n    )\r\n    return response.data or []\r\n\r\n\r\ndef get_all_transactions(user_email: str) -> dict:\r\n    """Geeft ALLE transacties van een gebruiker terug, gegroepeerd per holding_id."""\r\n    client = get_supabase_client()\r\n    response = (\r\n        client.table("portfolio_transactions")\r\n        .select("*")\r\n        .eq("user_email", hash_email(user_email))\r\n        .order("transaction_date", desc=False)\r\n        .execute()\r\n    )\r\n    grouped: dict = {}\r\n    for tx in (response.data or []):\r\n        grouped.setdefault(tx["holding_id"], []).append(tx)\r\n    return grouped\r\n\r\n\r\ndef delete_transaction(transaction_id: int, user_email: str) -> None:\r\n    """Verwijdert 1 transactie (bv. per ongeluk verkeerd ingevoerd)."""\r\n    client = get_supabase_client()\r\n    client.table("portfolio_transactions").delete() \\\r\n        .eq("id", transaction_id).eq("user_email", hash_email(user_email)).execute()\r\n\r\n\r\ndef update_holding_value(holding_id: int, user_email: str, position_value: float, value_currency: str = "EUR", day_change_pct: float = None) -> None:\r\n    """Werkt de LAATST BEREKENDE waarde van 1 positie bij (shares x actuele koers x wisselkoers), inclusief in welke valuta die staat, en de dagverandering (%) -- \'gratis\' meegenomen bij dezelfde refresh."""\r\n    client = get_supabase_client()\r\n    update_data = {"position_value": position_value, "value_currency": value_currency}\r\n    if day_change_pct is not None:\r\n        update_data["day_change_pct"] = day_change_pct\r\n    client.table("portfolio_holdings").update(update_data) \\\r\n        .eq("id", holding_id).eq("user_email", hash_email(user_email)).execute()\r\n\r\n\r\ndef delete_holding(holding_id: int, user_email: str) -> None:\r\n    """\r\n    Verwijdert een positie. Filtert OOK op user_email als extra\r\n    veiligheidslaag (voorkomt dat iemand een ID van een ander zou kunnen\r\n    raden en diens positie verwijderen).\r\n    """\r\n    client = get_supabase_client()\r\n    client.table("portfolio_holdings").delete().eq("id", holding_id).eq("user_email", hash_email(user_email)).execute()\r\n\r\n\r\ndef get_last_price_refresh(user_email: str):\r\n    """Geeft het tijdstip van de laatste waarde-update terug (of None als nog nooit gedaan)."""\r\n    client = get_supabase_client()\r\n    response = client.table("user_preferences").select("last_price_refresh_at").eq("user_email", hash_email(user_email)).execute()\r\n    if response.data and response.data[0].get("last_price_refresh_at"):\r\n        return response.data[0]["last_price_refresh_at"]\r\n    return None\r\n\r\n\r\ndef set_last_price_refresh(user_email: str, timestamp_iso: str) -> None:\r\n    """Slaat het tijdstip van de zojuist uitgevoerde waarde-update op (voor de rate-limit)."""\r\n    client = get_supabase_client()\r\n    client.table("user_preferences").upsert({\r\n        "user_email": hash_email(user_email),\r\n        "last_price_refresh_at": timestamp_iso,\r\n    }).execute()\r\n\r\n\r\ndef get_user_preferences(user_email: str) -> dict:\r\n    """\r\n    Geeft de e-mail-voorkeuren (en premium-status) van deze gebruiker terug.\r\n    Als er nog geen rij bestaat (nieuwe gebruiker), gelden de\r\n    standaardwaarden: WEL de persoonlijke portfolio-mail, NIET de\r\n    signaal-mails (allemaal opt-in, per type), GEEN premium, EU als regio.\r\n    """\r\n    client = get_supabase_client()\r\n    hashed = hash_email(user_email)\r\n    response = client.table("user_preferences").select("*").eq("user_email", hashed).execute()\r\n    if response.data:\r\n        return response.data[0]\r\n    return {\r\n        "user_email": hashed, "wants_portfolio_email": True,\r\n        "wants_daily_email": False, "is_premium": False, "email_region": "EU",\r\n        "wants_momentocrats_email": False, "wants_snowball_email": False, "wants_rocket_email": False,\r\n    }\r\n\r\n\r\ndef set_user_preferences(\r\n    user_email: str, wants_portfolio_email: bool,\r\n    wants_daily_email: bool = False, email_region: str = "EU",\r\n    wants_momentocrats_email: bool = False, wants_snowball_email: bool = False,\r\n    wants_rocket_email: bool = False,\r\n) -> None:\r\n    """Slaat de e-mail-voorkeuren op (maakt een nieuwe rij aan, of werkt de bestaande bij)."""\r\n    client = get_supabase_client()\r\n    client.table("user_preferences").upsert({\r\n        "user_email": hash_email(user_email),\r\n        "wants_portfolio_email": wants_portfolio_email,\r\n        "wants_daily_email": wants_daily_email,\r\n        "email_region": email_region,\r\n        "wants_momentocrats_email": wants_momentocrats_email,\r\n        "wants_snowball_email": wants_snowball_email,\r\n        "wants_rocket_email": wants_rocket_email,\r\n    }).execute()\r\n\r\n\r\ndef set_signal_email_preference(user_email: str, signal_key: str, value: bool) -> None:\r\n    """\r\n    Zet 1 losse signaal-mail-voorkeur (bv. vanaf de Discover-pagina zelf,\r\n    zonder de andere voorkeuren te moeten meesturen).\r\n    """\r\n    valid_keys = {"wants_momentocrats_email", "wants_snowball_email", "wants_rocket_email"}\r\n    if signal_key not in valid_keys:\r\n        raise ValueError(f"Onbekende signaal-sleutel: {signal_key}")\r\n    client = get_supabase_client()\r\n    client.table("user_preferences").upsert({\r\n        "user_email": hash_email(user_email),\r\n        signal_key: value,\r\n    }).execute()\r\n\r\n\r\ndef is_premium_user(user_email: str, ignore_free_for_all: bool = False) -> bool:\r\n    """\r\n    Handmatig te zetten (via Supabase) totdat er een echt betaalsysteem is.\r\n\r\n    ignore_free_for_all: zet op True voor content die ECHT premium moet\r\n    blijven, ook tijdens de \'iedereen premium\'-testfase (bv. de download\r\n    van het Smart DCA-script -- eenmaal weggegeven, krijg je \'m niet\r\n    terug, in tegenstelling tot bv. extra rijen in een signalenlijst).\r\n    """\r\n    if not ignore_free_for_all:\r\n        try:\r\n            if st.secrets.get("app", {}).get("premium_free_for_all", False):\r\n                return True\r\n        except Exception:\r\n            pass\r\n    prefs = get_user_preferences(user_email)\r\n    return bool(prefs.get("is_premium", False))\r\n\r\n\r\ndef set_premium_status(user_email: str, is_premium: bool) -> None:\r\n    """Zet de premium-status, aangeroepen nadat een Stripe-betaling geverifieerd is."""\r\n    client = get_supabase_client()\r\n    client.table("user_preferences").upsert({\r\n        "user_email": hash_email(user_email),\r\n        "is_premium": is_premium,\r\n    }).execute()\r\n\r\n\r\ndef set_stripe_customer_id(user_email: str, stripe_customer_id: str) -> None:\r\n    """Onthoudt welke Stripe-klant bij dit e-mailadres hoort (voor het portaal en de dagelijkse abonnement-check)."""\r\n    client = get_supabase_client()\r\n    client.table("user_preferences").upsert({\r\n        "user_email": hash_email(user_email),\r\n        "stripe_customer_id": stripe_customer_id,\r\n    }).execute()\r\n\r\n\r\ndef get_stripe_customer_id(user_email: str):\r\n    prefs = get_user_preferences(user_email)\r\n    return prefs.get("stripe_customer_id")\r\n\r\n\r\ndef get_all_premium_users_with_stripe_id() -> list:\r\n    """\r\n    Voor de dagelijkse abonnement-check: alle premium-gebruikers die een\r\n    Stripe-klant-ID hebben. LET OP: \'user_email\' in het resultaat is de\r\n    HASH (niet het leesbare adres) -- gebruik get_real_email() als je\r\n    het echte adres nodig hebt (bv. om een mail te sturen), en geef de\r\n    hash gewoon door aan set_premium_status() (die herkent \'m via het\r\n    veiligheidsnet in hash_email() en hasht \'m niet nog een keer).\r\n    """\r\n    client = get_supabase_client()\r\n    response = client.table("user_preferences").select("user_email, stripe_customer_id") \\\r\n        .eq("is_premium", True).execute()\r\n    return [row for row in response.data if row.get("stripe_customer_id")]\r\n\r\n\r\ndef get_cash_value(user_email: str) -> float:\r\n    """Geeft het opgeslagen, niet-ge\xc3\xafnvesteerde kapitaal terug (0.0 als nog niet ingesteld)."""\r\n    prefs = get_user_preferences(user_email)\r\n    return float(prefs.get("cash_value") or 0.0)\r\n\r\n\r\ndef set_cash_value(user_email: str, cash_value: float) -> None:\r\n    client = get_supabase_client()\r\n    client.table("user_preferences").upsert({\r\n        "user_email": hash_email(user_email),\r\n        "cash_value": cash_value,\r\n    }).execute()\r\n\r\n\r\nDEFAULT_RISK_PROFILE = {\r\n    "investment_horizon": "medium",\r\n    "risk_tolerance": "balanced",\r\n    "max_position_pct": 25.0,\r\n    "max_sector_pct": 40.0,\r\n    "target_cash_pct": 10.0,\r\n}\r\n\r\n\r\ndef get_risk_profile(user_email: str) -> dict:\r\n    """Geeft het risicoprofiel terug (wizard-antwoorden), met verstandige standaardwaarden."""\r\n    prefs = get_user_preferences(user_email)\r\n    profile = dict(DEFAULT_RISK_PROFILE)\r\n    for key in DEFAULT_RISK_PROFILE:\r\n        if prefs.get(key) is not None:\r\n            profile[key] = prefs[key]\r\n    return profile\r\n\r\n\r\ndef set_risk_profile(\r\n    user_email: str, investment_horizon: str, risk_tolerance: str,\r\n    max_position_pct: float, max_sector_pct: float, target_cash_pct: float,\r\n) -> None:\r\n    client = get_supabase_client()\r\n    client.table("user_preferences").upsert({\r\n        "user_email": hash_email(user_email),\r\n        "investment_horizon": investment_horizon,\r\n        "risk_tolerance": risk_tolerance,\r\n        "max_position_pct": max_position_pct,\r\n        "max_sector_pct": max_sector_pct,\r\n        "target_cash_pct": target_cash_pct,\r\n    }).execute()\r\n\r\n\r\ndef reset_risk_profile(user_email: str) -> None:\r\n    """Zet het risicoprofiel terug naar de standaardwaarden."""\r\n    set_risk_profile(user_email, **DEFAULT_RISK_PROFILE)\r\n\r\n\r\ndef get_last_seen_weekly_signals_date(user_email: str) -> str:\r\n    """Geeft de datum terug waarop deze gebruiker de weekly-signalen voor het laatst zag (of None)."""\r\n    client = get_supabase_client()\r\n    response = (\r\n        client.table("user_preferences")\r\n        .select("last_seen_weekly_signals_date")\r\n        .eq("user_email", hash_email(user_email))\r\n        .execute()\r\n    )\r\n    if response.data:\r\n        return response.data[0].get("last_seen_weekly_signals_date")\r\n    return None\r\n\r\n\r\ndef set_last_seen_weekly_signals_date(user_email: str, date_str: str) -> None:\r\n    """\r\n    Markeert dat deze gebruiker de weekly-signalen van \'date_str\' heeft\r\n    gezien -- upsert, want de rij bestaat mogelijk nog niet als de\r\n    gebruiker nog nooit eerdere voorkeuren heeft opgeslagen.\r\n    """\r\n    client = get_supabase_client()\r\n    client.table("user_preferences").upsert({\r\n        "user_email": hash_email(user_email),\r\n        "last_seen_weekly_signals_date": date_str,\r\n    }, on_conflict="user_email").execute()\r\n\r\n\r\ndef save_score_snapshot(user_email: str, score: float) -> None:\r\n    """\r\n    Slaat de Portfolio Health Score van vandaag op -- idempotent (overschrijft\r\n    gewoon als er al een snapshot van vandaag bestaat, dankzij de unique-\r\n    constraint op user_email+date). Veilig om bij elk paginabezoek aan te roepen.\r\n    """\r\n    client = get_supabase_client()\r\n    today = datetime.now().date().isoformat()\r\n    client.table("portfolio_score_history").upsert({\r\n        "user_email": hash_email(user_email),\r\n        "date": today,\r\n        "score": score,\r\n    }, on_conflict="user_email,date").execute()\r\n\r\n\r\ndef get_score_days_ago(user_email: str, days_ago: int = 7) -> float:\r\n    """\r\n    Geeft de meest recente opgeslagen score terug van OP OF VOOR \'days_ago\'\r\n    dagen geleden (niet exact op de dag, want er is niet altijd een\r\n    snapshot van precies die datum). Geeft None terug als er niets is.\r\n    """\r\n    client = get_supabase_client()\r\n    target_date = (datetime.now().date() - timedelta(days=days_ago)).isoformat()\r\n    response = (\r\n        client.table("portfolio_score_history")\r\n        .select("score")\r\n        .eq("user_email", hash_email(user_email))\r\n        .lte("date", target_date)\r\n        .order("date", desc=True)\r\n        .limit(1)\r\n        .execute()\r\n    )\r\n    if response.data:\r\n        return float(response.data[0]["score"])\r\n    return None\r\n\r\n\r\ndef get_all_users_with_holdings() -> dict[str, list[dict]]:\r\n    """\r\n    Geeft ALLE gebruikers en hun posities terug, gegroepeerd per (gehasht)\r\n    e-mailadres. Gebruikt door het wekelijkse geplande script (niet door\r\n    het dashboard zelf) om iedereen een persoonlijke e-mail te kunnen\r\n    sturen -- de sleutels hier zijn hashes, gebruik get_real_email() om\r\n    het echte adres op te zoeken v\xc3\xb3\xc3\xb3r het versturen.\r\n    """\r\n    client = get_supabase_client()\r\n    response = client.table("portfolio_holdings").select("*").execute()\r\n\r\n    grouped: dict[str, list[dict]] = {}\r\n    for row in response.data:\r\n        grouped.setdefault(row["user_email"], []).append(row)\r\n    return grouped\r\n\r\n\r\ndef add_deep_dive(\r\n    user_email: str, ticker: str, naam: str,\r\n    business_overview: str = None, investment_thesis: str = None,\r\n    management_assessment: str = None,\r\n    bear_case: str = None, valuation_view: str = None,\r\n    interested_price: float = None, catalysts: str = None,\r\n    position_sizing_plan: str = None, sell_criteria: str = None,\r\n    conclusion: str = None, market_snapshot: dict = None,\r\n    sell_trigger_price: float = None, sell_trigger_date: str = None,\r\n    thesis_score: int = None, management_score: int = None,\r\n    bear_case_score: int = None, valuation_score: int = None,\r\n    catalysts_score: int = None,\r\n    technical_analysis: str = None, technical_analysis_score: int = None,\r\n) -> int:\r\n    """\r\n    Slaat een NIEUWE versie van een deep-dive op (nooit overschrijven --\r\n    elke keer een nieuwe rij, zodat je kijk-verandering over tijd\r\n    zichtbaar blijft). Geeft de nieuwe id terug.\r\n\r\n    \'market_snapshot\' (optioneel): de automatisch aangeleverde marktdata\r\n    op het moment van opslaan (prijs, 52wk-hi/lo, marktkap, sector,\r\n    dividendrendement, signalen-kruisverband, sector-rotatie) -- een\r\n    \'foto op dat moment\', zodat oude versies hun eigen, destijds-geldige\r\n    cijfers bewaren i.p.v. steeds de HUIDIGE cijfers te tonen.\r\n\r\n    \'sell_trigger_price\'/\'sell_trigger_date\' (optioneel): automatisch te\r\n    checken verkoop-triggers -- komen terug op Today zodra de prijs dat\r\n    niveau bereikt, of die datum is aangebroken. \'sell_criteria\' (los,\r\n    vrije tekst) blijft de plek voor een GEBEURTENIS-trigger (bv. \'als ze\r\n    2 kwartalen missen\') -- dat kunnen we niet automatisch verifi\xc3\xabren,\r\n    dus dat blijft een handmatig te checken herinnering op deze pagina.\r\n\r\n    \'*_score\' (optioneel, 1-10): een cijfer per oordeel-onderdeel, ALTIJD\r\n    in dezelfde richting (\'hoger = gunstiger voor een koopbeslissing\') --\r\n    dus ook bear_case_score: hoog = de risico\'s zijn goed te overzien,\r\n    niet \'de risico\'s zijn ernstig\'. Het gemiddelde van de ingevulde\r\n    scores geeft een totaalcijfer per deep-dive.\r\n    """\r\n    client = get_supabase_client()\r\n    row = {\r\n        "user_email": hash_email(user_email),\r\n        "ticker": ticker,\r\n        "naam": naam,\r\n        "business_overview": business_overview,\r\n        "investment_thesis": investment_thesis,\r\n        "management_assessment": management_assessment,\r\n        "bear_case": bear_case,\r\n        "valuation_view": valuation_view,\r\n        "interested_price": interested_price,\r\n        "catalysts": catalysts,\r\n        "position_sizing_plan": position_sizing_plan,\r\n        "sell_criteria": sell_criteria,\r\n        "conclusion": conclusion,\r\n        "sell_trigger_price": sell_trigger_price,\r\n        "sell_trigger_date": sell_trigger_date,\r\n        "thesis_score": thesis_score,\r\n        "management_score": management_score,\r\n        "bear_case_score": bear_case_score,\r\n        "valuation_score": valuation_score,\r\n        "catalysts_score": catalysts_score,\r\n        "technical_analysis": technical_analysis,\r\n        "technical_analysis_score": technical_analysis_score,\r\n    }\r\n    if market_snapshot:\r\n        row.update(market_snapshot)\r\n    response = client.table("deep_dives").insert(row).execute()\r\n    return response.data[0]["id"]\r\n\r\n\r\ndef get_deep_dives_for_ticker(user_email: str, ticker: str) -> list:\r\n    """Geeft alle versies voor 1 ticker terug, meest recente eerst."""\r\n    client = get_supabase_client()\r\n    response = (\r\n        client.table("deep_dives")\r\n        .select("*")\r\n        .eq("user_email", hash_email(user_email))\r\n        .eq("ticker", ticker)\r\n        .order("created_at", desc=True)\r\n        .execute()\r\n    )\r\n    return response.data or []\r\n\r\n\r\ndef get_all_deep_dive_tickers(user_email: str) -> list:\r\n    """\r\n    Geeft 1 samenvattend overzicht terug -- per ticker de MEEST RECENTE\r\n    versie (voor de overzichtslijst), gesorteerd op laatst bijgewerkt.\r\n    """\r\n    client = get_supabase_client()\r\n    response = (\r\n        client.table("deep_dives")\r\n        .select("*")\r\n        .eq("user_email", hash_email(user_email))\r\n        .order("created_at", desc=True)\r\n        .execute()\r\n    )\r\n    latest_per_ticker = {}\r\n    for row in (response.data or []):\r\n        if row["ticker"] not in latest_per_ticker:\r\n            latest_per_ticker[row["ticker"]] = row\r\n    return sorted(latest_per_ticker.values(), key=lambda r: r["created_at"], reverse=True)\r\n\r\n\r\ndef delete_deep_dive(deep_dive_id: int, user_email: str) -> None:\r\n    """Verwijdert 1 specifieke versie (bv. per ongeluk aangemaakt)."""\r\n    client = get_supabase_client()\r\n    client.table("deep_dives").delete().eq("id", deep_dive_id).eq("user_email", hash_email(user_email)).execute()\r\n\r\n\r\ndef update_deep_dive(deep_dive_id: int, user_email: str, **fields) -> None:\r\n    """\r\n    Werkt EEN BESTAANDE versie bij (i.p.v. een nieuwe toe te voegen) --\r\n    voor het corrigeren van een typefout, of het aanvullen van een enkel\r\n    onderdeel zonder alle andere velden opnieuw te moeten uitschrijven.\r\n    Dit is bewust iets anders dan add_deep_dive(): dat maakt een NIEUWE,\r\n    aparte \'kijk op dit moment\'-versie, dit past de HUIDIGE versie aan.\r\n    """\r\n    client = get_supabase_client()\r\n    client.table("deep_dives").update(fields).eq("id", deep_dive_id).eq("user_email", hash_email(user_email)).execute()\r\n\r\n\r\ndef add_email_subscriber(email: str, region: str) -> tuple:\r\n    """\r\n    Meldt een e-mailadres aan voor de dagelijkse mail, ZONDER account.\r\n    Slaat een ONBEVESTIGDE rij op met een uniek bevestigings- en\r\n    uitschrijftoken, en geeft BEIDE terug (voor de bevestigingsmail,\r\n    die ook meteen een uitschrijflink bevat). Als het adres al bestaat\r\n    (bv. iemand vult 2x hetzelfde adres in), wordt de bestaande rij\r\n    bijgewerkt (nieuwe regio, nieuwe tokens) i.p.v. een dubbele rij.\r\n    """\r\n    import secrets\r\n    client = get_supabase_client()\r\n    confirmation_token = secrets.token_urlsafe(32)\r\n    unsubscribe_token = secrets.token_urlsafe(32)\r\n    client.table("email_subscribers").upsert({\r\n        "email": email.strip().lower(),\r\n        "email_region": region,\r\n        "confirmed": False,\r\n        "confirmation_token": confirmation_token,\r\n        "unsubscribe_token": unsubscribe_token,\r\n    }, on_conflict="email").execute()\r\n    return confirmation_token, unsubscribe_token\r\n\r\n\r\ndef confirm_email_subscriber(confirmation_token: str) -> bool:\r\n    """Bevestigt een e-mail-abonnement via het token uit de bevestigingsmail. Geeft False terug als het token onbekend is."""\r\n    client = get_supabase_client()\r\n    response = client.table("email_subscribers").select("id").eq("confirmation_token", confirmation_token).execute()\r\n    if not response.data:\r\n        return False\r\n    client.table("email_subscribers").update({\r\n        "confirmed": True,\r\n        "confirmed_at": datetime.now().isoformat(),\r\n    }).eq("confirmation_token", confirmation_token).execute()\r\n    return True\r\n\r\n\r\ndef unsubscribe_email_subscriber(unsubscribe_token: str) -> bool:\r\n    """Meldt een e-mailadres af via het token uit de mail zelf. Geeft False terug als het token onbekend is."""\r\n    client = get_supabase_client()\r\n    response = client.table("email_subscribers").select("id").eq("unsubscribe_token", unsubscribe_token).execute()\r\n    if not response.data:\r\n        return False\r\n    client.table("email_subscribers").delete().eq("unsubscribe_token", unsubscribe_token).execute()\r\n    return True\r\n\r\n\r\ndef get_confirmed_email_subscribers(region: str) -> list:\r\n    """Geeft alle BEVESTIGDE, niet-ingelogde abonnees voor deze regio terug (email + unsubscribe_token)."""\r\n    client = get_supabase_client()\r\n    response = (\r\n        client.table("email_subscribers")\r\n        .select("email, unsubscribe_token")\r\n        .eq("email_region", region)\r\n        .eq("confirmed", True)\r\n        .execute()\r\n    )\r\n    return response.data or []\r\n\r\n\r\ndef upload_deep_dive_image(\r\n    user_email: str, deep_dive_id: int, file_bytes: bytes, filename: str,\r\n    content_type: str, caption: str = None,\r\n) -> str:\r\n    """\r\n    Uploadt een afbeelding naar Supabase Storage en legt een referentie\r\n    (+ bijschrift) vast in deep_dive_images. Geeft de publieke URL terug.\r\n    Een unieke bestandsnaam (met een willekeurige component) voorkomt dat\r\n    2 uploads met dezelfde oorspronkelijke bestandsnaam elkaar overschrijven.\r\n    """\r\n    import uuid\r\n    client = get_supabase_client()\r\n    unique_filename = f"{deep_dive_id}_{uuid.uuid4().hex}_{filename}"\r\n    client.storage.from_("deep-dive-images").upload(\r\n        unique_filename, file_bytes, {"content-type": content_type}\r\n    )\r\n    public_url = client.storage.from_("deep-dive-images").get_public_url(unique_filename)\r\n    client.table("deep_dive_images").insert({\r\n        "deep_dive_id": deep_dive_id,\r\n        "user_email": hash_email(user_email),\r\n        "image_url": public_url,\r\n        "storage_path": unique_filename,\r\n        "caption": caption,\r\n    }).execute()\r\n    return public_url\r\n\r\n\r\ndef get_deep_dive_images(deep_dive_id: int) -> list:\r\n    """Geeft alle afbeeldingen voor 1 specifieke deep-dive-versie terug, oudste eerst."""\r\n    client = get_supabase_client()\r\n    response = (\r\n        client.table("deep_dive_images")\r\n        .select("*")\r\n        .eq("deep_dive_id", deep_dive_id)\r\n        .order("uploaded_at")\r\n        .execute()\r\n    )\r\n    return response.data or []\r\n\r\n\r\ndef delete_deep_dive_image(image_id: int, user_email: str) -> None:\r\n    """Verwijdert een afbeelding -- zowel het bestand uit Storage als de database-rij."""\r\n    client = get_supabase_client()\r\n    hashed_email = hash_email(user_email)\r\n    response = (\r\n        client.table("deep_dive_images")\r\n        .select("storage_path")\r\n        .eq("id", image_id)\r\n        .eq("user_email", hashed_email)\r\n        .execute()\r\n    )\r\n    if response.data:\r\n        storage_path = response.data[0]["storage_path"]\r\n        try:\r\n            client.storage.from_("deep-dive-images").remove([storage_path])\r\n        except Exception:\r\n            pass  # het bestand is mogelijk al weg -- de database-rij verwijderen we hoe dan ook\r\n    client.table("deep_dive_images").delete().eq("id", image_id).eq("user_email", hashed_email).execute()\r\n\r\n\r\ndef get_performance_snapshot(user_email: str) -> dict:\r\n    """\r\n    Haalt de laatst opgeslagen Performance-snapshot op (indien aanwezig)\r\n    -- gebruikt om de Performance-pagina INSTANT te tonen i.p.v. bij elk\r\n    bezoek alles opnieuw (traag) te herberekenen.\r\n    """\r\n    client = get_supabase_client()\r\n    hashed_email = hash_email(user_email)\r\n    response = client.table("performance_snapshots").select("*").eq("user_email", hashed_email).execute()\r\n    return response.data[0] if response.data else None\r\n\r\n\r\ndef save_performance_snapshot(\r\n    user_email: str, overall_return_pct: float, total_pnl: float,\r\n    earliest_date: str, checkpoint_results: list, value_series: list, performance_rows: list,\r\n) -> None:\r\n    """Slaat een nieuwe Performance-snapshot op (overschrijft de vorige -- we bewaren alleen de laatste)."""\r\n    client = get_supabase_client()\r\n    hashed_email = hash_email(user_email)\r\n    client.table("performance_snapshots").upsert({\r\n        "user_email": hashed_email,\r\n        "computed_at": datetime.now().isoformat(),\r\n        "overall_return_pct": overall_return_pct,\r\n        "total_pnl": total_pnl,\r\n        "earliest_date": earliest_date,\r\n        "checkpoint_results": checkpoint_results,\r\n        "value_series": value_series,\r\n        "performance_rows": performance_rows,\r\n    }).execute()\r\n\n\ndef get_roic_trend_history(tickers: list) -> dict:\n    """\n    Haalt de LAATST BEKENDE ROIC-trend per ticker op (van de vorige\n    Portfolio Watch-run) -- gebruikt om te bepalen of een \'dalende ROIC\'-\n    signalering deze week ECHT NIEUW is, i.p.v. elke week opnieuw dezelfde,\n    al-langer-bekende trend te tonen. Per TICKER bijgehouden (niet per\n    gebruiker) -- de ROIC-trend van een aandeel is voor iedereen hetzelfde,\n    dus geen zin om dit per gebruiker te dupliceren.\n    """\n    if not tickers:\n        return {}\n    client = get_supabase_client()\n    response = client.table("roic_trend_history").select("ticker,last_roic_trend").in_("ticker", tickers).execute()\n    return {row["ticker"]: row["last_roic_trend"] for row in response.data}\n\n\ndef save_roic_trend_history(ticker_trends: dict) -> None:\n    """Slaat de HUIDIGE ROIC-trend per ticker op, als \'vorige stand\' voor de volgende Portfolio Watch-run."""\n    if not ticker_trends:\n        return\n    client = get_supabase_client()\n    rows = [\n        {"ticker": ticker, "last_roic_trend": trend, "last_checked_at": datetime.now().isoformat()}\n        for ticker, trend in ticker_trends.items()\n    ]\n    client.table("roic_trend_history").upsert(rows, on_conflict="ticker").execute()\n'

WEEKLY_BATCH_CONTENT = b'"""\nWekelijks batch-script: draait de gedeelde screener EN stuurt elke\ngeregistreerde gebruiker een persoonlijke e-mail over hun eigen portfolio.\n\nBedoeld om te draaien via GitHub Actions (dus GEEN Streamlit-context --\nleest configuratie via omgevingsvariabelen, niet via st.secrets zoals\nhet dashboard zelf doet).\n\nBenodigde omgevingsvariabelen (als GitHub Actions secrets, of lokaal in .env):\n  SUPABASE_URL, SUPABASE_ANON_KEY\n  EMAIL_SMTP_SERVER, EMAIL_SMTP_PORT, EMAIL_ADDRESS, EMAIL_APP_PASSWORD\n\nGebruik: python weekly_batch.py\n"""\nfrom __future__ import annotations\n\nimport os\n\nimport pandas as pd\nfrom dotenv import load_dotenv\nfrom supabase import create_client\n\nload_dotenv()\n\nimport screener\nfrom portfolio_watch import check_holding, build_email_body\nfrom database import get_roic_trend_history, save_roic_trend_history\nfrom emailer import send_email\n\n\ndef get_supabase_client():\n    url = os.environ["SUPABASE_URL"]\n    key = os.environ["SUPABASE_ANON_KEY"]\n    return create_client(url, key)\n\n\ndef get_real_email(email_hash: str) -> str:\n    """\n    Zoekt het echte, verstuurbare e-mailadres op bij een hash -- nodig\n    omdat portfolio_holdings/user_preferences alleen de hash kennen, niet\n    het leesbare adres zelf (zie database.py\'s module-docstring).\n    """\n    client = get_supabase_client()\n    response = client.table("user_identity").select("email").eq("email_hash", email_hash).execute()\n    if response.data:\n        return response.data[0]["email"]\n    return None\n\n\ndef get_all_users_with_holdings() -> dict:\n    """\n    Geeft alle gebruikers en hun ACTIEVE, EIGEN posities terug, gegroepeerd\n    per (gehasht) e-mailadres. Filtert expliciet op is_watchlist=false EN\n    shares > 0 -- zonder deze filters kwamen watchlist-items en al-\n    verkochte posities (shares=0, blijven soms als rij staan i.p.v.\n    verwijderd) ook mee in de Portfolio Watch-mail, wat precies de bron\n    was van \'ik krijg info over posities die ik al verkocht heb\'.\n    """\n    client = get_supabase_client()\n    response = (\n        client.table("portfolio_holdings")\n        .select("*")\n        .eq("is_watchlist", False)\n        .gt("shares", 0)\n        .execute()\n    )\n\n    grouped: dict[str, list[dict]] = {}\n    for row in response.data:\n        grouped.setdefault(row["user_email"], []).append(row)\n    return grouped\n\n\ndef get_all_preferences() -> dict:\n    """Geeft de e-mail-voorkeuren van ALLE gebruikers terug (sleutel = gehasht e-mailadres)."""\n    client = get_supabase_client()\n    response = client.table("user_preferences").select("*").execute()\n    return {row["user_email"]: row for row in response.data}\n\n\ndef run_screener_shared() -> None:\n    """\n    Draait de gedeelde screener 1x -- de resultaten (CSV\'s, incl. Snowball\n    Signal en Rocket List) zijn voor iedereen zichtbaar op de website.\n    send_own_email=False, want de vaste mail naar het eigen GitHub-\n    secrets-adres zou dubbel op kunnen tellen met de per-gebruiker-opt-in-\n    mail hieronder (run_weekly_signals_emails) als dat hetzelfde adres is.\n    """\n    print("=== Gedeelde screener draaien (publiek, voor iedereen zichtbaar) ===")\n    screener.main(send_own_email=False)\n\n\ndef _format_momentocrats_row(row) -> str:\n    return (f"[score {row[\'score\']}] {row[\'ticker\']}: flipped {row[\'weken_geleden\']} week(en) ago "\n            f"({row[\'sinds_omslag_pct\']:+.2f}% since)")\n\n\ndef _format_snowball_row(row) -> str:\n    return (f"{row[\'ticker\']}: ROIC {row[\'roic_pct\']:.1f}%, "\n            f"{row[\'afwijking_fair_value_pct\']:+.1f}% vs. fair value")\n\n\ndef _format_rocket_row(row) -> str:\n    return (f"{row[\'ticker\']}: {row[\'groei_pct\']:.1f}% growth, "\n            f"{row[\'relatieve_sterkte\']:+.1f}% relative strength")\n\n\nSIGNAL_TYPES = {\n    "momentocrats": {\n        "pref_key": "wants_momentocrats_email", "csv": "supertrend_signals.csv",\n        "title": "Momentocrats", "emoji": "\xf0\x9f\x93\xa1", "sort_by": "score", "sort_asc": False,\n        "formatter": _format_momentocrats_row,\n    },\n    "snowball": {\n        "pref_key": "wants_snowball_email", "csv": "snowball_signals.csv",\n        "title": "Snowballers", "emoji": "\xf0\x9f\x90\xa6", "sort_by": "afwijking_fair_value_pct", "sort_asc": True,\n        "formatter": _format_snowball_row,\n    },\n    "rocket": {\n        "pref_key": "wants_rocket_email", "csv": "rocket_list_signals.csv",\n        "title": "Rocket List", "emoji": "\xf0\x9f\x9a\x80", "sort_by": "groei_pct", "sort_asc": False,\n        "formatter": _format_rocket_row,\n    },\n}\n\n\ndef build_weekly_signals_email(sections: list, is_premium: bool = False, daily_flips_text: str = "", daily_flips_html: str = "") -> tuple:\n    """\n    Bouwt 1 gecombineerde mail voor alle signaal-types die deze gebruiker\n    heeft aangevinkt, plus (optioneel) vrijdag\'s dagelijkse flips.\n\n    Toont altijd top 3 per signaal, OOK voor premium -- een mail met\n    tientallen regels per signaal is geen prettige samenvatting meer,\n    dat is precies waar Discover (met een scrollbare tabel) voor is.\n    De \'is_premium\'-parameter blijft bestaan voor later (zodra premium\n    functioneel is), maar be\xc3\xafnvloedt de mail-inhoud nu bewust niet.\n\n    sections: lijst van dicts met keys \'title\', \'emoji\', \'df\', \'formatter\'.\n    daily_flips_text/daily_flips_html: optioneel, van build_daily_flips_section() --\n    leeg als er niks te melden was (dan wordt deze sectie gewoon overgeslagen).\n    """\n    display_limit = 3\n    text_lines = ["Good morning from Hesty\'s -- your weekly signals are in.", ""]\n    html_sections_list = []\n\n    for section in sections:\n        total_this_section = len(section["df"])\n        top_n = section["df"].head(display_limit)\n        text_lines.append(f"{section[\'emoji\']} {section[\'title\']} (top {len(top_n)} of {total_this_section} total):")\n        for _, row in top_n.iterrows():\n            text_lines.append(f"  - {section[\'formatter\'](row)}")\n        text_lines.append("")\n\n        rows_html = "".join(\n            f"<li style=\'padding:4px 0;color:#101825;\'>{section[\'formatter\'](row)}</li>"\n            for _, row in top_n.iterrows()\n        )\n        html_sections_list.append(f"""\n        <h4 style="color:#101825; font-size:16px; margin:20px 0 8px 0;">{section[\'emoji\']} {section[\'title\']}</h4>\n        <ul style="margin:0; padding-left:20px; font-size:14px;">{rows_html}</ul>\n        """)\n\n    if daily_flips_text:\n        text_lines.append(daily_flips_text)\n    if daily_flips_html:\n        html_sections_list.append(daily_flips_html)\n\n    text_lines += [\n        "See the full lists, sector rotation, and top movers under Discover on the site.",\n        "",\n        "-- Hesty\'s, your personal investment assistant",\n        "",\n        "This is a screener, not investment advice.",\n    ]\n    text_body = "\\n".join(text_lines)\n\n    html_body = f"""\n    <div style="font-family: -apple-system, \'Segoe UI\', Roboto, Arial, sans-serif; max-width: 600px; margin: 0 auto; background:#ffffff;">\n        <div style="background:#101825; padding: 28px 24px; border-radius: 12px 12px 0 0;">\n            <div style="color:#1FAE96; font-size:13px; font-weight:600; letter-spacing:1px; text-transform:uppercase;">Hesty\'s Weekly</div>\n            <div style="color:#EAEDF1; font-size:22px; font-weight:700; margin-top:4px;">Your weekly signals are in</div>\n        </div>\n        <div style="padding: 24px; border: 1px solid #E5E8EC; border-top: none; border-radius: 0 0 12px 12px;">\n            {\'\'.join(html_sections_list)}\n            <p style="margin-top:20px; font-size:14px; color:#5B6472; line-height:1.5;">\n                See the full lists, sector rotation, and top movers under\n                <a href="https://hestys.streamlit.app/?view=discover" style="color:#1FAE96; font-weight:600; text-decoration:none;">Discover</a> on the site.\n            </p>\n            <p style="margin-top:24px; font-size:14px; color:#101825; font-weight:600;">&mdash; Hesty\'s, your personal investment assistant</p>\n            <p style="margin-top:16px; font-size:12px; color:#9AA1AC; font-style:italic;">This is a screener, not investment advice.</p>\n        </div>\n    </div>\n    """\n    return text_body, html_body\n\n\ndef run_weekly_signals_emails(preferences: dict, daily_flips_text: str = "", daily_flips_html: str = "") -> None:\n    """\n    Stuurt 1 gecombineerde mail per gebruiker, met alleen de signaal-types\n    waar diegene zich voor heeft aangemeld (top 3 gratis / top 10 premium),\n    plus (optioneel) vrijdag\'s dagelijkse flips erbij.\n\n    daily_flips_text/daily_flips_html: alleen toegevoegd aan mails die\n    sowieso al verstuurd worden (dus gebruikers met minstens 1 signaal-\n    type aangevinkt) -- geen nieuwe categorie gebruikers die anders\n    niks zouden ontvangen.\n    """\n    print("\\n=== Wekelijkse signalen-mails versturen aan opt-in-gebruikers ===")\n\n    # Laad elke CSV maar 1x, niet per gebruiker opnieuw\n    csv_cache = {}\n    for key, config in SIGNAL_TYPES.items():\n        if os.path.exists(config["csv"]):\n            df = pd.read_csv(config["csv"])\n            if not df.empty:\n                df = df.sort_values(config["sort_by"], ascending=config["sort_asc"])\n                csv_cache[key] = df\n\n    for user_email_hash, prefs in preferences.items():\n        sections = []\n        for key, config in SIGNAL_TYPES.items():\n            if not prefs.get(config["pref_key"]):\n                continue\n            if key not in csv_cache:\n                continue\n            sections.append({\n                "title": config["title"], "emoji": config["emoji"],\n                "df": csv_cache[key], "formatter": config["formatter"],\n            })\n\n        if not sections:\n            continue\n\n        real_email = get_real_email(user_email_hash)\n        if not real_email:\n            print(f"  Kon geen e-mailadres vinden voor hash {user_email_hash[:12]}... -- overgeslagen.")\n            continue\n\n        is_premium = bool(prefs.get("is_premium", False))\n        print(f"  {real_email} ({\'premium\' if is_premium else \'free\'}): {\', \'.join(s[\'title\'] for s in sections)}")\n        text_body, html_body = build_weekly_signals_email(\n            sections, is_premium=is_premium,\n            daily_flips_text=daily_flips_text, daily_flips_html=daily_flips_html,\n        )\n        total_signals = sum(len(s["df"]) for s in sections)\n        subject = f"Hesty\'s Weekly: {total_signals} new signal(s) this week"\n        send_email(subject=subject, body_text=text_body, body_html=html_body, to_email=real_email)\n\n\ndef run_portfolio_emails(preferences: dict) -> None:\n    """\n    Checkt en mailt elke geregistreerde gebruiker zijn eigen, persoonlijke\n    portfolio -- behalve als hij dat expliciet heeft uitgezet. Standaard AAN\n    (ook voor gebruikers die nog nooit hun voorkeuren hebben aangepast).\n    """\n    print("\\n=== Persoonlijke portfolio-e-mails versturen ===")\n    users = get_all_users_with_holdings()\n    print(f"{len(users)} gebruiker(s) gevonden met een portfolio.")\n\n    for user_email_hash, holdings in users.items():\n        user_prefs = preferences.get(user_email_hash, {})\n        if not user_prefs.get("wants_portfolio_email", True):\n            print(f"\\n--- {user_email_hash[:12]}...: heeft de portfolio-mail uitgezet, overgeslagen ---")\n            continue\n\n        real_email = get_real_email(user_email_hash)\n        if not real_email:\n            print(f"\\n--- {user_email_hash[:12]}...: geen e-mailadres gevonden, overgeslagen ---")\n            continue\n\n        print(f"\\n--- {real_email} ({len(holdings)} positie(s)) ---")\n        results = []\n        for holding in holdings:\n            result = check_holding(holding["naam"], holding["ticker"])\n            if result:\n                result["shares"] = holding.get("shares")\n                results.append(result)\n\n        if not results:\n            print("  Geen van de posities kon gecheckt worden -- geen mail verstuurd.")\n            continue\n\n        df = pd.DataFrame(results)\n\n        # Alleen NIEUWE ROIC-dalingen laten meetellen in \'Worth a closer\n        # look\' -- zelfde logica als portfolio_watch.py\'s eigen main().\n        previous_roic_trends = get_roic_trend_history(df["ticker"].tolist())\n        df["roic_decline_is_new"] = df.apply(\n            lambda r: r["roic_trend"] == "dalend" and previous_roic_trends.get(r["ticker"]) != "dalend",\n            axis=1,\n        )\n\n        text_body, html_body = build_email_body(df)\n        n_changed = int(df["recent_gewijzigd"].sum())\n        n_earnings = int((df["earnings_surprise_pct"].notna()).sum())\n        subject_parts = []\n        if n_changed > 0:\n            subject_parts.append(f"{n_changed} trend change(s)")\n        if n_earnings > 0:\n            subject_parts.append(f"{n_earnings} earnings update(s)")\n        subject = f"Portfolio Watch: {\', \'.join(subject_parts)}" if subject_parts else "Portfolio Watch: no notable changes this week"\n\n        send_email(subject=subject, body_text=text_body, body_html=html_body, to_email=real_email)\n\n        # De HUIDIGE ROIC-stand opslaan als \'vorige week\' voor de volgende\n        # run -- onafhankelijk per ticker (niet per gebruiker), aangezien\n        # de ROIC-trend van een aandeel voor iedereen hetzelfde is.\n        save_roic_trend_history(dict(zip(df["ticker"], df["roic_trend"])))\n\n\ndef run_daily_flip_scan_for_weekly() -> None:\n    """\n    Draait de dagelijkse flip-scan OPNIEUW, specifiek voor de zaterdag-\n    weekly-mail -- dit vangt de VOLLEDIGE, net-afgeronde vrijdag-sessie op.\n    (De reguliere vrijdagochtend-scan draaide namelijk vroeg, VOORDAT de\n    Amerikaanse beurs zelfs maar open was, en liet dus donderdag-vs-\n    woensdag\'s beweging zien, niet de volledige vrijdag-sessie.)\n\n    Schrijft dezelfde bestanden als de dagelijkse scan (supertrend_signals_daily.csv,\n    top_movers.csv) -- verstuurt zelf GEEN aparte mail, de resultaten worden\n    hieronder in de weekly-mail verwerkt.\n    """\n    import screener_daily\n    print("\\n=== Dagelijkse flip-scan opnieuw draaien (voor de volledige vrijdag-sessie) ===")\n    screener_daily.main(send_own_email=False)\n\n\ndef build_daily_flips_section() -> tuple:\n    """\n    Bouwt een tekst- en HTML-fragment met de belangrijkste flips uit de\n    zojuist opnieuw gedraaide dagelijkse scan (dus: vrijdag\'s volledige\n    sessie) -- toegevoegd aan de zaterdag-weekly-mail, i.p.v. hiervoor een\n    aparte mail te sturen. Geeft (leeg, leeg) terug als er geen data is\n    of geen signalen waren, zodat de aanroeper deze sectie dan gewoon\n    kan overslaan.\n    """\n    if not os.path.exists("supertrend_signals_daily.csv"):\n        return "", ""\n    df_daily = pd.read_csv("supertrend_signals_daily.csv")\n    if df_daily.empty:\n        return "", ""\n\n    df_daily = df_daily.sort_values("score", ascending=False)\n    display_limit = 5\n    top_n = df_daily.head(display_limit)\n\n    text_lines = [f"\xf0\x9f\x93\x85 Friday\'s daily flips (top {len(top_n)} of {len(df_daily)} total):"]\n    for _, row in top_n.iterrows():\n        text_lines.append(\n            f"  - [{row[\'score\']}] {row[\'ticker\']}: {row[\'prijs_bij_omslag\']} -> {row[\'prijs_nu\']} "\n            f"({row[\'sinds_omslag_pct\']:+.2f}%)"\n        )\n    text_lines.append("")\n    text_fragment = "\\n".join(text_lines)\n\n    rows_html = "".join(\n        f"<li style=\'padding:4px 0;color:#101825;\'>[{row[\'score\']}] {row[\'ticker\']}: "\n        f"{row[\'prijs_bij_omslag\']} &rarr; {row[\'prijs_nu\']} ({row[\'sinds_omslag_pct\']:+.2f}%)</li>"\n        for _, row in top_n.iterrows()\n    )\n    html_fragment = f"""\n    <h4 style="color:#101825; font-size:16px; margin:20px 0 8px 0;">\xf0\x9f\x93\x85 Friday\'s daily flips (top {len(top_n)} of {len(df_daily)} total)</h4>\n    <ul style="margin:0; padding-left:20px; font-size:14px;">{rows_html}</ul>\n    """\n    return text_fragment, html_fragment\n\n\ndef run_saturday() -> None:\n    """\n    Zaterdag: de gedeelde screener + wekelijkse signalen-mails (Momentocrats/\n    Snowballers/Rocket List) -- nu AANGEVULD met vrijdag\'s volledige\n    dagelijkse flips (i.p.v. daarvoor een aparte mail te sturen). Portfolio\n    Watch is BEWUST verplaatst naar zondag (zie run_sunday) -- anders kreeg\n    je 2-3 mails tegelijk op zaterdagochtend.\n    """\n    run_screener_shared()\n    run_daily_flip_scan_for_weekly()\n    all_preferences = get_all_preferences()\n    daily_flips_text, daily_flips_html = build_daily_flips_section()\n    run_weekly_signals_emails(all_preferences, daily_flips_text=daily_flips_text, daily_flips_html=daily_flips_html)\n\n\ndef run_sunday() -> None:\n    """Zondag: alleen Portfolio Watch -- apart van de zaterdag-signalen, geen mail-opeenstapeling meer."""\n    all_preferences = get_all_preferences()\n    run_portfolio_emails(all_preferences)\n\n\nif __name__ == "__main__":\n    import sys\n    mode = sys.argv[1] if len(sys.argv) > 1 else "saturday"\n    if mode == "saturday":\n        run_saturday()\n    elif mode == "sunday":\n        run_sunday()\n    else:\n        raise ValueError(f"Onbekende modus: \'{mode}\' -- gebruik \'saturday\' of \'sunday\'.")\n    print("\\nKlaar.")\n'

with open("portfolio_watch.py", "wb") as f:
    f.write(PORTFOLIO_WATCH_CONTENT)
with open("database.py", "wb") as f:
    f.write(DATABASE_CONTENT)
with open("weekly_batch.py", "wb") as f:
    f.write(WEEKLY_BATCH_CONTENT)
print("Weggeschreven: portfolio_watch.py, database.py, weekly_batch.py")
print()
